export const TEMPLATE_FILES: Record<string, string> = {
  "package.json": "{\n  \"name\": \"reel-project\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"scripts\": {\n    \"dev\": \"remotion studio src/index.ts\",\n    \"still\": \"remotion still src/index.ts Reel out/still.png\",\n    \"render\": \"remotion render src/index.ts Reel out/reel.mp4\"\n  },\n  \"dependencies\": {\n    \"@remotion/bundler\": \"4.0.484\",\n    \"@remotion/cli\": \"4.0.484\",\n    \"@remotion/renderer\": \"4.0.484\",\n    \"react\": \"19.2.7\",\n    \"react-dom\": \"19.2.7\",\n    \"remotion\": \"4.0.484\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"19.2.17\",\n    \"typescript\": \"6.0.3\"\n  }\n}\n",
  "remotion.config.ts": "import { Config } from \"@remotion/cli/config\"\n\n/**\n * Remotion 配置。渲染走 reel 子Agent 的原生渲染库（不经 CLI），此处只影响手动 `npx remotion` 调试；\n * 保持与子Agent 的默认档一致：720p 以上一律 JPEG 中间帧、并发交给子Agent 决策。\n */\nConfig.setVideoImageFormat(\"jpeg\")\nConfig.setJpegQuality(82)\nConfig.setOverwriteOutput(true)\n",
  "src/Root.tsx": "import { Composition } from \"remotion\"\nimport { Film } from \"./film/Film\"\nimport { FPS, TOTAL } from \"./film/timeline\"\n\n/**\n * 合成注册。竖屏/方屏交付时在这里再加一条 `<Composition>`（同一组件 + 不同 width/height），\n * 渲染时用 `composition` 参数选择。\n */\nexport const RemotionRoot: React.FC = () => (\n  <>\n    <Composition id=\"Reel\" component={Film} durationInFrames={TOTAL} fps={FPS} width={1920} height={1080} />\n  </>\n)\n",
  "src/film/Film.tsx": "/**\n * 全片装配：按 timeline 的镜头窗口铺开镜头、音效与解说。\n *\n * 扩容方式：在 `timeline.SHOTS` 增加镜头窗口 → 在这里加一条 `<Sequence>` → 在 `scenes/` 下新建该镜组件。\n * 镜头组件一律渲染在 `<Sequence>` 内（其 `useCurrentFrame()` 即镜头内相对帧）。\n */\nimport { AbsoluteFill, Audio, Sequence, staticFile } from \"remotion\"\nimport { CAPTIONS, SFX, SHOTS, sfxDuration } from \"./timeline\"\nimport { Caption } from \"./ui\"\nimport { SceneOpen } from \"./scenes/SceneOpen\"\nimport { SceneGrid } from \"./scenes/SceneGrid\"\nimport { SceneFlow } from \"./scenes/SceneFlow\"\nimport { SceneOutro } from \"./scenes/SceneOutro\"\n\nexport const Film: React.FC = () => (\n  <AbsoluteFill style={{ backgroundColor: \"#0b0d12\" }}>\n    {/* 音效：钉帧表驱动（占位为空表；填表后自动生效） */}\n    {SFX.map((s, i) => (\n      <Sequence key={`sfx-${i}`} from={s.from} durationInFrames={sfxDuration(s)}>\n        <Audio src={staticFile(s.src)} volume={s.volume} />\n      </Sequence>\n    ))}\n\n    <Sequence from={SHOTS.open.from} durationInFrames={SHOTS.open.duration}>\n      <SceneOpen />\n    </Sequence>\n    <Sequence from={SHOTS.grid.from} durationInFrames={SHOTS.grid.duration}>\n      <SceneGrid />\n    </Sequence>\n    <Sequence from={SHOTS.flow.from} durationInFrames={SHOTS.flow.duration}>\n      <SceneFlow />\n    </Sequence>\n    <Sequence from={SHOTS.outro.from} durationInFrames={SHOTS.outro.duration}>\n      <SceneOutro />\n    </Sequence>\n\n    {/* 解说条（跨镜头，统一挂在这一层，章节组件里不要再嵌 Caption） */}\n    {CAPTIONS.map((c, i) => (\n      <Sequence key={`cap-${i}`} from={c.from} durationInFrames={c.duration}>\n        <Caption text={c.text} duration={c.duration} />\n      </Sequence>\n    ))}\n  </AbsoluteFill>\n)\n",
  "src/film/PageCam.tsx": "/**\n * 2.5D 页面相机 —— 一切\"真实页面\"镜头的地基（把真实截图当成可运镜的平面）。\n *\n * 两条不能降档的技法：\n * 1. **放大必须走 CSS `zoom`（布局级缩放），不能走 transform scale**。3D 合成层若用 transform scale 放大，\n *    Chromium 会先在布局尺寸上栅格化再由 GPU 放大——页面内的文字必然发糊（与相机/景深参数无关）。\n *    `zoom` 放大的是布局盒本身，页面按放大后的设备尺寸重新栅格化，从高清源向下采样，字形边缘保持锐利。\n * 2. **坐标系换算**：`zoom` 缩放元素本地坐标空间，页面点 (cx,cy) 落在 (cx*zoom, cy*zoom)，平移量因此是\n *    `960/zoom − cx`（Ty 同理）；旋转以 (cx,cy) 为 transform-origin，焦点在屏幕上不动。\n *    漏掉 `/zoom` 会让推近时取景跑偏。\n *\n * 素材要求：截图按显示尺寸的 **2–4 倍**采集（pageW 为布局宽，纹理像素宽为 pageW × 倍率），\n * 这样放大到 zoom≈2 仍有余量；1x 纹理的镜头请把 zoom 控制在 1.15 以内（超过即糊边，重采 2x 而不是降 zoom）。\n * 同一页面建议采 **2–3 个状态**（不同会话/面板展开收起）——全片用同一张固定状态纹理，运镜再讲究也显假。\n */\nimport { Easing, Img, interpolate, staticFile, useCurrentFrame } from \"remotion\"\nimport type { ReactNode } from \"react\"\n\nexport type CamKey = {\n  /** 镜头内相对帧。 */\n  frame: number\n  /** 页面坐标（CSS px）中要对准视口中心的点。 */\n  cx: number\n  cy: number\n  /** 缩放：1 = 1 CSS px 映射 1 输出 px。 */\n  zoom: number\n  /** 俯仰（正 = 上沿远离，像俯看桌面）。 */\n  rotX?: number\n  /** 偏航（正 = 右边后退，即从左侧看）。 */\n  rotY?: number\n  /** 画面内旋转。 */\n  rotZ?: number\n  /** 透视强度（px，越小越强）。 */\n  persp?: number\n}\n\nconst lerp = (a: number, b: number, t: number): number => a + (b - a) * t\n\nexport const PageCam: React.FC<{\n  /** 纹理路径（相对 public/，如 \"textures/home-2x.png\"）。 */\n  src: string\n  /** 页面布局宽（与采集时视口宽一致）。 */\n  pageW: number\n  /** 页面布局高（整页高；只截首屏时给视口高）。 */\n  pageH: number\n  keys: CamKey[]\n  /** 页面坐标系里的叠加层（注记/高亮框/光标），随页面一起被相机推动。 */\n  children?: ReactNode\n  blur?: number\n  saturate?: number\n  ease?: (t: number) => number\n  /** 近似的景深：页面远处（上方）加一层渐变模糊。 */\n  dof?: { focusY: number; strength: number }\n  bg?: string\n  /** 图片填充方式：整页截图用默认（拉伸到 pageW×pageH）；元素级抠图用 \"contain\"。 */\n  fit?: \"fill\" | \"contain\"\n}> = ({ src, pageW, pageH, keys, children, blur = 0, saturate = 1, ease = Easing.bezier(0.33, 0, 0.15, 1), dof, bg = \"#0b0d12\", fit = \"fill\" }) => {\n  const frame = useCurrentFrame()\n  let a = keys[0]\n  let b = keys[keys.length - 1]\n  for (let i = 0; i < keys.length - 1; i++) {\n    if (frame >= keys[i].frame && frame <= keys[i + 1].frame) {\n      a = keys[i]\n      b = keys[i + 1]\n      break\n    }\n  }\n  const t = a.frame === b.frame ? 1 : interpolate(frame, [a.frame, b.frame], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\", easing: ease })\n  const cx = lerp(a.cx, b.cx, t)\n  const cy = lerp(a.cy, b.cy, t)\n  const zoom = lerp(a.zoom, b.zoom, t)\n  const rotX = lerp(a.rotX ?? 0, b.rotX ?? 0, t)\n  const rotY = lerp(a.rotY ?? 0, b.rotY ?? 0, t)\n  const rotZ = lerp(a.rotZ ?? 0, b.rotZ ?? 0, t)\n  const persp = lerp(a.persp ?? 1400, b.persp ?? 1400, t)\n\n  const filters: string[] = []\n  if (blur > 0) filters.push(`blur(${blur}px)`)\n  if (saturate !== 1) filters.push(`saturate(${saturate})`)\n\n  const has3D = keys.some((k) => k.rotX !== undefined || k.rotY !== undefined || k.rotZ !== undefined || k.persp !== undefined)\n\n  const plane = (\n    <div\n      style={{\n        position: \"absolute\",\n        width: pageW,\n        height: pageH,\n        zoom,\n        transform: has3D\n          ? `translate(${960 / zoom - cx}px, ${540 / zoom - cy}px) rotateY(${rotY}deg) rotateX(${rotX}deg) rotateZ(${rotZ}deg)`\n          : `translate(${960 / zoom - cx}px, ${540 / zoom - cy}px)`,\n        transformOrigin: has3D ? `${cx}px ${cy}px` : \"0 0\",\n        transformStyle: has3D ? \"preserve-3d\" : undefined,\n        filter: filters.length ? filters.join(\" \") : undefined,\n      }}\n    >\n      <Img src={staticFile(src)} style={{ position: \"absolute\", width: pageW, height: pageH, objectFit: fit }} />\n      {children}\n    </div>\n  )\n\n  return (\n    <div style={{ position: \"absolute\", inset: 0, overflow: \"hidden\", backgroundColor: bg }}>\n      {has3D ? (\n        <div style={{ position: \"absolute\", inset: 0, perspective: `${persp * zoom}px`, perspectiveOrigin: \"960px 540px\" }}>{plane}</div>\n      ) : (\n        plane\n      )}\n      {dof ? (\n        <div\n          style={{\n            position: \"absolute\",\n            left: 0,\n            right: 0,\n            top: 0,\n            height: Math.max(0, dof.focusY),\n            backdropFilter: `blur(${dof.strength}px)`,\n            maskImage: \"linear-gradient(to bottom, rgba(0,0,0,1) 0%, rgba(0,0,0,1) 45%, rgba(0,0,0,0) 100%)\",\n            pointerEvents: \"none\",\n          }}\n        />\n      ) : null}\n    </div>\n  )\n}\n\n/** 页面坐标系里的注记框（高亮某个元素时用；坐标即截图里的 CSS px）。 */\nexport const PageBox: React.FC<{\n  x: number\n  y: number\n  w: number\n  h: number\n  delay?: number\n  color?: string\n  label?: string\n  labelSide?: \"left\" | \"right\"\n}> = ({ x, y, w, h, delay = 0, color = \"#7aa2f7\", label, labelSide = \"right\" }) => {\n  const frame = useCurrentFrame()\n  const on = interpolate(frame, [delay, delay + 34], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\", easing: Easing.bezier(0.22, 1, 0.36, 1) })\n  return (\n    <>\n      <div\n        style={{\n          position: \"absolute\",\n          left: x,\n          top: y,\n          width: w,\n          height: h,\n          border: `1px solid ${color}`,\n          borderRadius: 6,\n          boxShadow: `0 0 30px ${color}44`,\n          opacity: on * 0.95,\n          transform: `scale(${0.985 + on * 0.015})`,\n        }}\n      />\n      {label ? (\n        <div\n          style={{\n            position: \"absolute\",\n            left: labelSide === \"right\" ? x + w + 18 : x - 18,\n            top: y + h / 2,\n            transform: `translate(${labelSide === \"right\" ? \"0\" : \"-100%\"}, -50%)`,\n            display: \"flex\",\n            alignItems: \"center\",\n            gap: 10,\n            opacity: on,\n          }}\n        >\n          <div style={{ width: 42, height: 1, backgroundColor: color, opacity: 0.7 }} />\n          <div\n            style={{\n              fontFamily: '\"Noto Sans CJK SC\",system-ui,sans-serif',\n              fontSize: 17,\n              letterSpacing: \"0.14em\",\n              color,\n              background: \"rgba(11,13,18,0.8)\",\n              border: \"1px solid rgba(255,255,255,0.1)\",\n              borderRadius: 999,\n              padding: \"7px 14px\",\n              whiteSpace: \"nowrap\",\n            }}\n          >\n            {label}\n          </div>\n        </div>\n      ) : null}\n    </>\n  )\n}\n",
  "src/film/scenes/SceneFlow.tsx": "/**\n * 示例镜头 ③：机制说明（环形节点流程：连线先画、节点后落位，配一组指标数字）。\n * 演示 `NodeFlow` 与 `DigitRoll`：机制类画面给\"结构 + 数字\"，比堆文字更易读。\n */\nimport { AbsoluteFill, useCurrentFrame } from \"remotion\"\nimport { C, F, T } from \"../theme\"\nimport { Backplate, DigitRoll, Headline, Kicker, NodeFlow, p } from \"../ui\"\nimport { COPY } from \"../timeline\"\n\nexport const SceneFlow: React.FC = () => {\n  const frame = useCurrentFrame()\n  return (\n    <AbsoluteFill>\n      <Backplate grid={140} glows={[{ x: 960, y: 540, r: 560, color: \"rgba(122,162,247,0.12)\", opacity: 0.85, delay: 10 }]}>\n        <div style={{ position: \"absolute\", left: 120, top: 96 }}>\n          <Kicker text={COPY.flowKicker} delay={4} align=\"left\" />\n        </div>\n        <div style={{ position: \"absolute\", left: 120, top: 168 }}>\n          <Headline text={COPY.flowTitle} size={52} delay={10} perChar={3} align=\"left\" />\n        </div>\n        <NodeFlow\n          nodes={COPY.flowNodes}\n          radius={224}\n          nodeSize={104}\n          delay={30}\n          nodeDelay={30}\n          nodeStep={30}\n          centerLabel={COPY.flowCenter}\n          centerSize={32}\n        />\n        <div style={{ position: \"absolute\", left: 0, right: 0, bottom: 96, display: \"flex\", justifyContent: \"center\", gap: 96 }}>\n          {COPY.flowMetrics.map((m, i) => (\n            <div key={m.label} style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 10, opacity: p(frame, 150 + i * 10, T.mid) }}>\n              <DigitRoll value={m.value} suffix={m.suffix} delay={152 + i * 10} size={72} />\n              <span style={{ fontFamily: F.sans, fontSize: 18, letterSpacing: \"0.24em\", color: C.textFaint }}>{m.label}</span>\n            </div>\n          ))}\n        </div>\n      </Backplate>\n    </AbsoluteFill>\n  )\n}\n",
  "src/film/scenes/SceneGrid.tsx": "/**\n * 示例镜头 ②：能力全景（左侧主张 + 右侧元素网格批量错峰入场，末尾点亮少数关键项）。\n * 演示 `Grid` 的用法：批量入场靠运动本身（越后越密），点光只给少数几个关键项、不群发。\n */\nimport { AbsoluteFill, useCurrentFrame } from \"remotion\"\nimport { C, F, T } from \"../theme\"\nimport { Backplate, Grid, Headline, Kicker, Rule, p } from \"../ui\"\nimport { COPY } from \"../timeline\"\n\nexport const SceneGrid: React.FC = () => {\n  const frame = useCurrentFrame()\n  return (\n    <AbsoluteFill>\n      <Backplate grid={96} glows={[{ x: 1420, y: 560, r: 520, color: \"rgba(122,162,247,0.14)\", opacity: 0.8, delay: 20 }]}>\n        <div style={{ position: \"absolute\", left: 140, top: 300, width: 620 }}>\n          <Kicker text={COPY.gridKicker} delay={6} align=\"left\" />\n          <div style={{ marginTop: 26 }}>\n            <Headline text={COPY.gridTitle} size={62} delay={14} perChar={3} align=\"left\" tracking=\"0.04em\" />\n          </div>\n          <div style={{ marginTop: 28 }}>\n            <Rule width={260} delay={40} from=\"left\" />\n          </div>\n          <div style={{ marginTop: 30, opacity: p(frame, 52, T.small), fontFamily: F.sans, fontSize: 22, lineHeight: 1.8, color: C.textDim, letterSpacing: \"0.02em\" }}>\n            {COPY.gridBody}\n          </div>\n          <div style={{ marginTop: 40, opacity: p(frame, 96, T.mid) }}>\n            <span style={{ fontFamily: F.mono, fontSize: 64, color: C.text }}>{COPY.gridCount}</span>\n            <span style={{ marginLeft: 16, fontFamily: F.sans, fontSize: 20, color: C.textFaint, letterSpacing: \"0.2em\" }}>{COPY.gridCountUnit}</span>\n          </div>\n        </div>\n        <div style={{ position: \"absolute\", left: 860, top: 250, width: 940, display: \"flex\", justifyContent: \"center\" }}>\n          <Grid\n            items={COPY.gridItems}\n            columns={4}\n            cellW={216}\n            cellH={66}\n            gap={14}\n            start={20}\n            span={110}\n            ignite={[0, 5, 9]}\n            igniteAt={150}\n          />\n        </div>\n      </Backplate>\n    </AbsoluteFill>\n  )\n}\n",
  "src/film/scenes/SceneOpen.tsx": "/**\n * 示例镜头 ①：品牌开场（准星描线 → 字标压印 → 副标 → tagline），落定后静止满 1 秒再走。\n * 这是全片唯一的\"仪式感\"镜头：一个主角（字标）、一条完整动作弧、一次高光（Wordmark 的光晕）。\n */\nimport { AbsoluteFill, useCurrentFrame } from \"remotion\"\nimport { C, F, T } from \"../theme\"\nimport { Backplate, Crosshair, Headline, Kicker, Rule, p } from \"../ui\"\nimport { COPY } from \"../timeline\"\n\nexport const SceneOpen: React.FC = () => {\n  const frame = useCurrentFrame()\n  const subOn = p(frame, 96, T.small)\n  const tagline = p(frame, 128, T.mid)\n  return (\n    <AbsoluteFill>\n      <Backplate grid={120} glows={[{ x: 960, y: 520, r: 620, color: \"rgba(122,162,247,0.20)\", opacity: 0.9, delay: 16 }]}>\n        <AbsoluteFill style={{ alignItems: \"center\", justifyContent: \"center\" }}>\n          <Crosshair w={720} h={340} delay={2} />\n          <div style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 20 }}>\n            <Headline text={COPY.brand} size={168} delay={40} perChar={6} tracking=\"0.22em\" weight={700} />\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 14, opacity: subOn }}>\n              <div style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: C.accent }} />\n              <span style={{ fontFamily: F.mono, fontSize: 18, letterSpacing: \"0.42em\", color: C.textDim }}>{COPY.brandSub}</span>\n            </div>\n          </div>\n          <div style={{ marginTop: 34, display: \"flex\", justifyContent: \"center\" }}>\n            <Rule width={520} delay={110} color=\"rgba(122,162,247,0.5)\" />\n          </div>\n          <div style={{ marginTop: 30, opacity: tagline, transform: `translateY(${(1 - tagline) * 10}px)` }}>\n            <span style={{ fontFamily: F.serif, fontSize: 34, letterSpacing: \"0.28em\", color: C.textDim }}>{COPY.tagline}</span>\n          </div>\n        </AbsoluteFill>\n        <div style={{ position: \"absolute\", left: 120, top: 96 }}>\n          <Kicker text={COPY.kicker} delay={118} size={14} align=\"left\" />\n        </div>\n      </Backplate>\n    </AbsoluteFill>\n  )\n}\n",
  "src/film/scenes/SceneOutro.tsx": "/**\n * 示例镜头 ④：结语（元素合影围住字标 → 字标落地 → 标语）。\n * 全片能量峰值：`Roster` 把已展示的元素按硬加速错峰收拢，字标随后压印并静止 ≥1 秒（R1）。\n */\nimport { AbsoluteFill, useCurrentFrame } from \"remotion\"\nimport { C, F, T } from \"../theme\"\nimport { Backplate, Headline, Roster, p } from \"../ui\"\nimport { COPY } from \"../timeline\"\n\nexport const SceneOutro: React.FC = () => {\n  const frame = useCurrentFrame()\n  const markOn = p(frame, 170, T.mid)\n  const tagline = p(frame, 214, T.mid)\n  return (\n    <AbsoluteFill>\n      <Backplate\n        glows={[\n          { x: 960, y: 540, r: 560, color: \"rgba(122,162,247,0.16)\", opacity: 0.9, delay: 40 },\n          { x: 620, y: 380, r: 320, color: \"rgba(224,176,112,0.10)\", opacity: 0.8, delay: 120 },\n        ]}\n        vignette={0.6}\n      >\n        <Roster items={COPY.rosterItems.map((text) => ({ text }))} start={30} span={130} delay={10} />\n        <AbsoluteFill style={{ alignItems: \"center\", justifyContent: \"center\" }}>\n          <div style={{ transform: \"translateY(-46px)\" }}>\n            <Headline text={COPY.brand} size={142} delay={170} perChar={6} tracking=\"0.24em\" weight={700} />\n          </div>\n          <div style={{ position: \"absolute\", top: \"62%\", opacity: tagline, transform: `translateY(${(1 - tagline) * 12}px)` }}>\n            <span style={{ fontFamily: F.serif, fontSize: 44, letterSpacing: \"0.2em\", color: C.text }}>{COPY.outroTagline}</span>\n          </div>\n          <div style={{ position: \"absolute\", top: \"71%\", opacity: p(frame, 236, T.small) }}>\n            <span style={{ fontFamily: F.sans, fontSize: 18, letterSpacing: \"0.42em\", color: C.textDim }}>{COPY.brandSub}</span>\n          </div>\n        </AbsoluteFill>\n        <div style={{ position: \"absolute\", left: 0, right: 0, bottom: 84, textAlign: \"center\", opacity: p(frame, 240, T.small) }}>\n          <span style={{ fontFamily: F.mono, fontSize: 17, letterSpacing: \"0.3em\", color: C.textFaint, opacity: markOn }}>{COPY.outroFoot}</span>\n        </div>\n      </Backplate>\n    </AbsoluteFill>\n  )\n}\n",
  "src/film/theme.ts": "/**\n * 设计 token —— 全片视觉与动效的唯一真相源。\n *\n * 这里的默认值是一套**中性的暗场占位色**，不是\"宣传片皮肤\"。按工作流第一条纪律：视觉语言必须\n * 从目标产品自身生长——开工第一步应当把本文件换成从产品提取的 tokens（字体家族与字重、字号层级、\n * 行高字距、圆角与间距、背景/表面/正文/强调/状态色、渐变与材质），片中所有标题、字幕、数字、\n * 字卡、版式、转场、粒子与光效都复用同一套值。改这一个文件即可换掉整片皮肤。\n */\nimport { Easing } from \"remotion\"\n\n/** 色板。accent 承担\"唯一强调色\"职责；多色相并发会把画面推向廉价。 */\nexport const C = {\n  bg: \"#0b0d12\",\n  bgSoft: \"#12151c\",\n  /** 玻璃表面（低不透明度白 + 背景模糊，配 Panel 使用）。 */\n  surface: \"rgba(255,255,255,0.045)\",\n  accent: \"#7aa2f7\",\n  accentSoft: \"rgba(122,162,247,0.18)\",\n  /** 暖色副调（只用于点缀：金尘、余晖）。 */\n  warm: \"#e0b070\",\n  text: \"#e9edf5\",\n  textDim: \"#98a2b6\",\n  textFaint: \"#5b6577\",\n  line: \"rgba(255,255,255,0.10)\",\n  lineStrong: \"rgba(255,255,255,0.18)\",\n  success: \"#5fd39a\",\n  danger: \"#e06c75\",\n  paper: \"#f2efe8\",\n  black: \"#000000\",\n} as const\n\n/**\n * 字体栈。中文字体必须**渲染机本机存在**（Remotion 走 Chromium 系统字体），\n * 故按\"常见开源中文字体 → 系统字体 → 通用族\"排列，末尾永远留通用族兜底。\n */\nexport const F = {\n  serif: '\"Noto Serif CJK SC\",\"Noto Serif SC\",\"Source Han Serif SC\",\"Songti SC\",Georgia,serif',\n  sans: '\"Noto Sans CJK SC\",\"Noto Sans SC\",\"Source Han Sans SC\",\"PingFang SC\",\"Microsoft YaHei\",system-ui,sans-serif',\n  mono: '\"JetBrains Mono\",\"DejaVu Sans Mono\",ui-monospace,SFMono-Regular,Menlo,monospace',\n} as const\n\n/**\n * 缓动族——**一个品牌一种动效嗓音**：入场/相机/批量/退场都从这里取，\n * 不允许各镜头自造曲线（混两套曲线读作拼盘）。\n */\nexport const EASE = {\n  /** 主入场（缓和出，最常用）。 */\n  out: Easing.bezier(0.22, 1, 0.36, 1),\n  /** 相机与位移（长时间运动不疲劳）。 */\n  cam: Easing.bezier(0.33, 0, 0.15, 1),\n  /** 对称进出（网格/整墙批量）。 */\n  inOut: Easing.bezier(0.4, 0, 0.2, 1),\n  /** 硬加速：批量入场越往后越密（批量元素的节奏感来源）。 */\n  accel: Easing.bezier(0.6, 0, 0.9, 0.4),\n  /** 起笔（微 anticipation）。 */\n  in: Easing.bezier(0.6, 0, 0.8, 0.2),\n  /** 弹性落定（仅用于\"新元素注册/落位\"这类需要一点活性的场合）。 */\n  lively: Easing.bezier(0.16, 1, 0.3, 1),\n} as const\n\n/**\n * 时值 token（帧 @30fps）。排时间线时**先划走 hold/rest 帧再排动效**——\n * 节奏偏好是单向的：观众只会说\"太快了\"，从不说\"太慢了\"。\n */\nexport const T = {\n  micro: 12,\n  small: 21,\n  mid: 34,\n  big: 48,\n  /** 关键信息/品牌字标落定后的完整静止（≥1s）。 */\n  hold: 30,\n  /** 批量动作收尾的呼吸。 */\n  rest: 15,\n  /** 相邻镜头的最小交棒缓冲。 */\n  gap: 6,\n} as const\n\nexport const clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v)\n\n/** 网格底纹（Backplate 用）：返回可直接塞进 backgroundImage 的 CSS。 */\nexport const gridCss = (size: number, color: string): string =>\n  `repeating-linear-gradient(to right, ${color} 0 1px, transparent 1px ${size}px), repeating-linear-gradient(to bottom, ${color} 0 1px, transparent 1px ${size}px)`\n\n/**\n * 确定性伪随机（mulberry32）。渲染必须逐帧可复现：**禁用 Math.random / Date.now**，\n * 一切\"随机感\"都从这里取，种子由调用方给定（同一画面每次渲染完全一致）。\n */\nexport const mulberry32 = (seed: number): (() => number) => {\n  let a = seed >>> 0\n  return () => {\n    a = (a + 0x6d2b79f5) >>> 0\n    let t = a\n    t = Math.imul(t ^ (t >>> 15), t | 1)\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296\n  }\n}\n\n/** 由索引派生的稳定伪随机（无需保存生成器状态，适合逐元素抖动）。 */\nexport const jitter = (index: number, salt = 1): number => {\n  const x = Math.sin(index * 12.9898 + salt * 78.233) * 43758.5453\n  return x - Math.floor(x)\n}\n",
  "src/film/timeline.ts": "/**\n * 时间线 —— 全片的唯一真相源：镜头窗口、文案、解说、音效钉帧都在这里。\n *\n * 组织约定：\n * - 镜头窗口用 `{ from, duration }` 表达，组件自己只关心\"镜头内相对帧\"（渲染在 `<Sequence>` 内）。\n * - 音效/解说都写**相对表达式**（`SHOTS.x.from + 偏移`），绝不在别处写死绝对帧号——\n *   时间线整体平移时全表自动跟随，不需要逐条重钉。\n * - 文案集中在 COPY：改词只改一处，镜头组件只负责排版与动效。\n * - 排期纪律：先划走 hold/rest 帧再排动效（品牌落定静止 ≥1s、批量收尾留 0.5s）。\n *   节奏偏好是单向的——观众只会说\"太快了\"。\n */\nexport const FPS = 30\n\nexport const SHOTS = {\n  /** ① 品牌开场：准星 → 字标压印 → 副标 → tagline，落定后静止满 1s。 */\n  open: { from: 0, duration: 150 },\n  /** ② 能力全景：左侧主张 + 右侧元素网格（末尾点亮少数关键项）。 */\n  grid: { from: 150, duration: 180 },\n  /** ③ 机制说明：环形节点流程（连线先画、节点后落）+ 指标数字滚动。 */\n  flow: { from: 330, duration: 230 },\n  /** ④ 结语：元素合影围住字标（全片能量峰值，字标落定后静止 ≥1s）。 */\n  outro: { from: 560, duration: 270 },\n} as const\n\nexport const TOTAL = 830 // 27.7s @30fps —— 示例片时长；替换成正式内容后按分镜重排\n\n/**\n * 示例文案。**这些是占位内容**：正式制作时应按目标产品的定位重写——\n * 标语要具体（带产品功能名与收益），抽象隐喻词一律具体化。\n */\nexport const COPY = {\n  brand: \"星轨\",\n  brandSub: \"ORBIT STUDIO\",\n  kicker: \"PRODUCT FILM\",\n  tagline: \"把复杂，讲清楚。\",\n\n  gridKicker: \"CAPABILITIES\",\n  gridTitle: \"能力全景\",\n  gridBody: \"四组能力、十二个模块，共用同一套视觉语言与操作习惯。\",\n  gridCount: \"12\",\n  gridCountUnit: \"MODULES\",\n  gridItems: [\n    \"巡检\",\n    \"编排\",\n    \"观测\",\n    \"归档\",\n    \"权限\",\n    \"审计\",\n    \"回滚\",\n    \"扩缩\",\n    \"调度\",\n    \"通知\",\n    \"报表\",\n    \"集成\",\n  ],\n\n  flowKicker: \"HOW IT WORKS\",\n  flowTitle: \"一条闭环\",\n  flowNodes: [\"采集\", \"编排\", \"执行\", \"归档\"],\n  flowCenter: \"闭环\",\n  flowMetrics: [\n    { label: \"自动化率\", value: 92, suffix: \"%\" },\n    { label: \"节点规模\", value: 240, suffix: \"+\" },\n    { label: \"平均恢复\", value: 3, suffix: \"s\" },\n  ],\n\n  rosterItems: [\"巡检\", \"编排\", \"观测\", \"归档\", \"权限\", \"审计\", \"回滚\", \"扩缩\", \"调度\", \"通知\"],\n  outroTagline: \"把复杂，讲清楚。\",\n  outroFoot: \"STORYBOARD · SHOT · CUT · MIX\",\n} as const\n\n/**\n * 解说字幕（叙述型片子不留\"哑巴段落\"：超过 3 秒的无解说动画段落应补一条）。\n * 品牌开场与结语保持干净——这两处靠画面本身说话。\n */\nexport const CAPTIONS: Array<{ from: number; duration: number; text: string }> = [\n  { from: SHOTS.grid.from + 26, duration: 92, text: \"一套视觉语言，贯穿全部模块\" },\n  { from: SHOTS.flow.from + 30, duration: 96, text: \"采集 → 编排 → 执行 → 归档，闭环自持\" },\n]\n\n/**\n * 音效钉帧表（占位为空）。\n *\n * 用法：把音频素材放进 `public/audio/`，然后按下面的形状逐条登记——\n * `{ from: SHOTS.<鏡>.from + 偏移, src: \"audio/xxx.mp3\", volume: 0.4, note: \"对应画面动作\" }`。\n * 纪律：有辨识度的画面动作要配拟音（点击/打字/落位各配各的）；音量按素材实际峰值给，\n * 不要照抄区间；长样本（>5s）用 `durationInFrames` 截断到与动作等长；\n * 结尾固定句式 riser → impact → sparkle。若配了 BGM，终渲出带 BGM / 无 BGM 两版。\n */\nexport const SFX: Array<{ from: number; src: string; volume: number; durationInFrames?: number; note?: string }> = []\n\n/** 默认播放窗：短样本（≤3s）统一给 90 帧；长样本请在表里显式给 durationInFrames。 */\nexport const sfxDuration = (s: { durationInFrames?: number }): number => s.durationInFrames ?? 90\n",
  "src/film/ui.tsx": "/**\n * 镜头原语 —— 全片共用的组件层（排版、光线、质感、面板、图元）。\n *\n * 用法约定：\n * - 组件默认按**当前序列的局部帧**计时（把镜头渲染在 `<Sequence>` 内，`useCurrentFrame()` 即从 0 起）；\n *   因此这里的 `delay` 一律写镜头内相对帧，镜头在时间线上平移时无需改动。\n * - 只暴露\"语义参数\"（文案、字号、强调色…），运动时值走 theme 的 token，不在调用处随手调曲线。\n * - 装饰性光效宁缺毋滥：一个镜头最多给主角一次高光（Glow 用作环境光时不占该名额）。\n */\nimport { interpolate, useCurrentFrame } from \"remotion\"\nimport type { CSSProperties, ReactNode } from \"react\"\nimport { C, EASE, F, T, clamp01, gridCss } from \"./theme\"\n\n/* ────────────────────────────── 进度与运动工具 ────────────────────────────── */\n\n/** 缓动进度：delay 起、dur 帧内按 ease 到 1（越界钳制）——所有入场动作的统一入口。 */\nexport const p = (frame: number, delay: number, dur: number, ease: (t: number) => number = EASE.out): number =>\n  clamp01(ease(interpolate(frame, [delay, delay + dur], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" })))\n\n/** 线性进度（颜色/亮度等不需要缓动的量）。 */\nexport const pl = (frame: number, delay: number, dur: number): number =>\n  clamp01(interpolate(frame, [delay, delay + dur], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" }))\n\n/**\n * 批量元素入场进度：错峰 + 硬加速（越往后越密）——\"越来越快\"是批量入场的节奏感来源，\n * 匀速铺开读作 PPT。`i` 为元素序号，`count` 总数，`start`/`span` 为整批的时间窗。\n */\nexport const accel = (frame: number, i: number, count: number, start: number, span: number): number => {\n  const t = interpolate(frame - start, [0, span], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" })\n  const biased = Math.pow(t, 0.72)\n  const slot = count <= 1 ? 0 : i / (count - 1)\n  return clamp01(interpolate(biased, [slot * 0.82, Math.min(1, slot * 0.82 + 0.18)], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" }))\n}\n\n/**\n * 跟随动作（follow-through）：把同一轨迹在 `frame − delay` 处采样即为\"拖尾层\"，\n * 每层给不同 delay 与幅度即成拖尾/影子层级。纯函数、无状态，逐帧可复现。\n */\nexport const lagged = <S,>(stateAt: (f: number) => S, frame: number, delay: number): S => stateAt(frame - delay)\n\n/**\n * 阻尼振荡（落地回弹/收束尾音）：t 为自撞击起的帧数，返回衰减到 0 的有符号偏移系数，\n * 乘上目标振幅即得回弹位移。closed-form，无模拟状态。\n */\nexport const dampedSettle = (t: number, freq = 0.1, damping = 0.15): number =>\n  t <= 0 ? 0 : Math.exp(-damping * t) * Math.sin(2 * Math.PI * freq * t)\n\n/* ────────────────────────────── 时间窗容器 ────────────────────────────── */\n\n/**\n * 时间窗：只在 `[start, start+span]` 内渲染 children，两端各 `fade` 帧淡入淡出——\n * 给\"限时出现的注记\"（某段动作期间才存在的标注框、光圈、辅助线）一个统一开关，\n * 免去每个镜头各写一套帧号分支。窗口按镜头局部帧计（与其余原语同一坐标系）。\n * `fade=0` 即硬切（不做插值）；fade 自动钳在窗口一半以内，避免淡入与淡出相撞。\n */\nexport const Show: React.FC<{\n  start: number\n  span: number\n  children: ReactNode\n  fade?: number\n  delay?: number\n}> = ({ start, span, children, fade = 6, delay = 0 }) => {\n  const frame = useCurrentFrame() - delay\n  if (frame < start || frame > start + span) return null\n  const f = Math.max(0, Math.min(fade, span / 2))\n  const opacity = f <= 0 ? 1 : Math.min(pl(frame, start, f), 1 - pl(frame, start + span - f, f))\n  return <div style={{ position: \"absolute\", inset: 0, opacity, pointerEvents: \"none\" }}>{children}</div>\n}\n\n/* ────────────────────────────── 底版 · 光线 · 质感 ────────────────────────────── */\n\n/** 环境光斑（呼吸）：用于给暗场一点\"活气\"，不占\"主角高光\"名额。 */\nexport const Glow: React.FC<{\n  x: number\n  y: number\n  r: number\n  color: string\n  opacity: number\n  delay?: number\n  breathe?: number\n  blur?: number\n}> = ({ x, y, r, color, opacity, delay = 0, breathe = 90, blur = 28 }) => {\n  const frame = useCurrentFrame()\n  const on = p(frame, delay, T.big)\n  const pulse = 1 + 0.04 * Math.sin((frame / breathe) * Math.PI * 2)\n  return (\n    <div\n      style={{\n        position: \"absolute\",\n        left: x - r,\n        top: y - r,\n        width: r * 2,\n        height: r * 2,\n        borderRadius: \"50%\",\n        background: `radial-gradient(circle, ${color} 0%, transparent 68%)`,\n        opacity: opacity * on,\n        transform: `scale(${pulse})`,\n        filter: `blur(${blur}px)`,\n        pointerEvents: \"none\",\n      }}\n    />\n  )\n}\n\n/** 扫描线质感（确定性：位移由帧号驱动，不用随机）——给纯色画面一点\"屏\"的味道。 */\nexport const Grain: React.FC<{ opacity?: number; lineHeight?: number }> = ({ opacity = 0.05, lineHeight = 3 }) => {\n  const frame = useCurrentFrame()\n  const shift = (frame * 1.7) % 4\n  return (\n    <div\n      style={{\n        position: \"absolute\",\n        inset: 0,\n        pointerEvents: \"none\",\n        opacity,\n        backgroundImage: \"repeating-linear-gradient(to bottom, rgba(255,255,255,0.5) 0 1px, transparent 1px 3px)\",\n        backgroundSize: `100% ${lineHeight + 1}px`,\n        backgroundPosition: `0 ${shift}px`,\n        mixBlendMode: \"overlay\",\n      }}\n    />\n  )\n}\n\n/** 暗场底版：底色 + 可选网格 + 环境光 + 暗角。镜头内容作为 children 叠在其上。 */\nexport const Backplate: React.FC<{\n  grid?: number\n  glows?: Array<{ x: number; y: number; r: number; color: string; opacity: number; delay?: number }>\n  vignette?: number\n  bg?: string\n  children?: ReactNode\n}> = ({ grid, glows = [], vignette = 0.55, bg = C.bg, children }) => (\n  <div style={{ position: \"absolute\", inset: 0, backgroundColor: bg, overflow: \"hidden\" }}>\n    {grid ? <div style={{ position: \"absolute\", inset: 0, backgroundImage: gridCss(grid, \"rgba(255,255,255,0.028)\") }} /> : null}\n    {glows.map((g, i) => (\n      <Glow key={i} {...g} />\n    ))}\n    {children}\n    {vignette > 0 ? (\n      <div\n        style={{\n          position: \"absolute\",\n          inset: 0,\n          background: `radial-gradient(ellipse at 50% 46%, transparent 42%, rgba(0,0,0,${vignette}) 100%)`,\n          pointerEvents: \"none\",\n        }}\n      />\n    ) : null}\n  </div>\n)\n\n/* ────────────────────────────── 排版层 ────────────────────────────── */\n\n/** 拉丁小标（眉题）：宽字距全大写，用于给段落定调。 */\nexport const Kicker: React.FC<{ text: string; delay?: number; color?: string; size?: number; align?: \"left\" | \"center\" }> = ({\n  text,\n  delay = 0,\n  color = C.accent,\n  size = 15,\n  align = \"center\",\n}) => {\n  const frame = useCurrentFrame()\n  const on = p(frame, delay, T.small)\n  return (\n    <div\n      style={{\n        fontFamily: F.sans,\n        fontSize: size,\n        letterSpacing: \"0.42em\",\n        textTransform: \"uppercase\",\n        color,\n        opacity: on * 0.92,\n        transform: `translateY(${(1 - on) * 8}px)`,\n        textAlign: align,\n        whiteSpace: \"pre\",\n      }}\n    >\n      {text}\n    </div>\n  )\n}\n\n/** 细线生长（分隔/收束用）。 */\nexport const Rule: React.FC<{\n  width: number\n  delay?: number\n  color?: string\n  thickness?: number\n  duration?: number\n  from?: \"left\" | \"center\"\n}> = ({ width, delay = 0, color = C.lineStrong, thickness = 1, duration = T.mid, from = \"center\" }) => {\n  const frame = useCurrentFrame()\n  const on = p(frame, delay, duration)\n  return (\n    <div\n      style={{\n        width: width * on,\n        height: thickness,\n        backgroundColor: color,\n        alignSelf: from === \"center\" ? \"center\" : \"flex-start\",\n        marginLeft: from === \"left\" ? 0 : undefined,\n      }}\n    />\n  )\n}\n\n/**\n * 大标题：逐字浮现（字距收紧 + 轻微上浮 + 模糊收敛）。\n * 语言无关——中文走衬线更沉稳，英文/代码标识走 `font` 显式指定等宽。\n */\nexport const Headline: React.FC<{\n  text: string\n  size?: number\n  delay?: number\n  perChar?: number\n  color?: string\n  font?: string\n  weight?: number\n  tracking?: string\n  lineHeight?: number\n  align?: \"left\" | \"center\"\n}> = ({ text, size = 76, delay = 0, perChar = 4, color = C.text, font = F.serif, weight = 600, tracking = \"0.06em\", lineHeight = 1.35, align = \"center\" }) => {\n  const frame = useCurrentFrame()\n  const chars = Array.from(text)\n  return (\n    <div\n      style={{\n        fontFamily: font,\n        fontSize: size,\n        fontWeight: weight,\n        letterSpacing: tracking,\n        lineHeight,\n        color,\n        display: \"flex\",\n        flexWrap: \"wrap\",\n        justifyContent: align === \"center\" ? \"center\" : \"flex-start\",\n      }}\n    >\n      {chars.map((ch, i) => {\n        const on = p(frame, delay + i * perChar, T.mid)\n        return (\n          <span\n            key={i}\n            style={{\n              opacity: on,\n              transform: `translateY(${(1 - on) * size * 0.16}px)`,\n              filter: on < 1 ? `blur(${(1 - on) * 5}px)` : undefined,\n              whiteSpace: \"pre\",\n            }}\n          >\n            {ch}\n          </span>\n        )\n      })}\n    </div>\n  )\n}\n\n/**\n * 品牌字标（正片开场与结语的关键记忆点）：主标压印 + 副标淡入。\n * **落定后必须静止 ≥1s**（R1）——本组件只负责\"落定\"，hold 由调用方排进时间线。\n */\nexport const Wordmark: React.FC<{\n  text: string\n  sub?: string\n  size?: number\n  delay?: number\n  color?: string\n  glow?: number\n  font?: string\n}> = ({ text, sub, size = 132, delay = 0, color = C.text, glow = 0.5, font = F.serif }) => {\n  const frame = useCurrentFrame()\n  const on = p(frame, delay, T.mid)\n  const settle = p(frame, delay + 6, T.big)\n  const subOn = p(frame, delay + T.mid, T.small)\n  return (\n    <div style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: size * 0.16 }}>\n      <div\n        style={{\n          fontFamily: font,\n          fontSize: size,\n          fontWeight: 700,\n          letterSpacing: \"0.22em\",\n          color,\n          opacity: on,\n          transform: `scale(${1.05 - settle * 0.05})`,\n          filter: on < 1 ? `blur(${(1 - on) * 6}px)` : undefined,\n          textShadow: glow > 0 ? `0 0 ${40 * settle}px ${C.accent}${Math.round(glow * settle * 255).toString(16).padStart(2, \"0\")}` : undefined,\n        }}\n      >\n        {text}\n      </div>\n      {sub ? (\n        <div style={{ fontFamily: F.sans, fontSize: size * 0.1, letterSpacing: \"0.5em\", color: C.textDim, opacity: subOn * 0.9 }}>{sub}</div>\n      ) : null}\n    </div>\n  )\n}\n\n/** 底部解说条（叙述型片子不留\"哑巴段落\"：超过 3s 的无解说动画段落应补一条）。 */\nexport const Caption: React.FC<{ text: string; duration: number; accent?: string; left?: number; bottom?: number; size?: number }> = ({\n  text,\n  duration,\n  accent = C.accent,\n  left = 120,\n  bottom = 92,\n  size = 25,\n}) => {\n  const frame = useCurrentFrame()\n  const inn = p(frame, 4, T.small)\n  const out = interpolate(frame, [duration - 14, duration - 2], [1, 0], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" })\n  return (\n    <div\n      style={{\n        position: \"absolute\",\n        left,\n        bottom,\n        display: \"flex\",\n        alignItems: \"center\",\n        gap: 18,\n        opacity: inn * out,\n        transform: `translateY(${(1 - inn) * 14}px)`,\n      }}\n    >\n      <div style={{ width: 3, height: size * 1.05, backgroundColor: accent, opacity: 0.9 }} />\n      <div style={{ fontFamily: F.sans, fontSize: size, letterSpacing: \"0.16em\", color: C.text, opacity: 0.94 }}>{text}</div>\n    </div>\n  )\n}\n\n/** 等宽文本块（命令 / 路径 / 代码 / 指标清单）：逐行浮现，可高亮若干行。 */\nexport const Mono: React.FC<{\n  lines: string[]\n  delay?: number\n  lineDelay?: number\n  size?: number\n  color?: string\n  highlight?: number[]\n  highlightColor?: string\n  align?: \"left\" | \"center\"\n}> = ({ lines, delay = 0, lineDelay = 6, size = 28, color = C.textDim, highlight = [], highlightColor = C.accent, align = \"left\" }) => {\n  const frame = useCurrentFrame()\n  return (\n    <div style={{ display: \"flex\", flexDirection: \"column\", gap: size * 0.55, alignItems: align === \"center\" ? \"center\" : \"flex-start\" }}>\n      {lines.map((line, i) => {\n        const on = p(frame, delay + i * lineDelay, T.small)\n        const hot = highlight.includes(i)\n        return (\n          <div\n            key={i}\n            style={{\n              fontFamily: F.mono,\n              fontSize: size,\n              color: hot ? highlightColor : color,\n              opacity: on,\n              transform: `translateX(${(1 - on) * -12}px)`,\n              whiteSpace: \"pre\",\n            }}\n          >\n            {line}\n          </div>\n        )\n      })}\n    </div>\n  )\n}\n\n/** 玻璃面板（承载一组信息时用它统一材质，别让每个元素各带一套圆角/描边）。 */\nexport const Panel: React.FC<{ children?: ReactNode; style?: CSSProperties; pad?: number; glow?: string; radius?: number }> = ({\n  children,\n  style,\n  pad = 28,\n  glow,\n  radius = 16,\n}) => (\n  <div\n    style={{\n      background: C.surface,\n      border: `1px solid ${C.line}`,\n      borderRadius: radius,\n      padding: pad,\n      backdropFilter: \"blur(14px)\",\n      boxShadow: glow ? `0 0 60px -10px ${glow}` : undefined,\n      ...style,\n    }}\n  >\n    {children}\n  </div>\n)\n\n/* ────────────────────────────── 镜头图元 ────────────────────────────── */\n\n/**\n * 准星（十字描线）。用于\"定位/瞄准\"语气的开场或强调：\n * 先横后纵描线，落位后压暗为基准线，可视为后续内容的坐标系。\n */\nexport const Crosshair: React.FC<{ w?: number; h?: number; delay?: number; color?: string; dim?: number }> = ({\n  w = 700,\n  h = 320,\n  delay = 0,\n  color = C.accent,\n  dim = 0.66,\n}) => {\n  const frame = useCurrentFrame()\n  const hx = p(frame, delay, T.mid)\n  const vx = p(frame, delay + 10, T.mid + 4)\n  const faded = 1 - p(frame, delay + T.big, T.mid) * dim\n  const line = (extra: CSSProperties): CSSProperties => ({ position: \"absolute\", backgroundColor: \"rgba(255,255,255,0.34)\", opacity: faded, ...extra })\n  const tick = (extra: CSSProperties): CSSProperties => ({ position: \"absolute\", backgroundColor: color, opacity: faded * 0.9, ...extra })\n  return (\n    <div style={{ position: \"absolute\", inset: 0, display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n      <div style={line({ width: w * hx, height: 1 })} />\n      <div style={line({ width: 1, height: h * vx })} />\n      <div style={tick({ width: 1, height: 12, transform: `translateX(${(-w / 2) * hx}px)` })} />\n      <div style={tick({ width: 1, height: 12, transform: `translateX(${(w / 2) * hx}px)` })} />\n      <div style={tick({ width: 12, height: 1, transform: `translateY(${(-h / 2) * vx}px)` })} />\n      <div style={tick({ width: 12, height: 1, transform: `translateY(${(h / 2) * vx}px)` })} />\n    </div>\n  )\n}\n\n/**\n * 元素网格：把一列标签/图标/字段按栅格铺满，批量错峰入场（越后越密），\n * 可选\"停一拍后点亮其中若干\"（把注意力交给少数关键项）。\n * 用于\"能力全景\"\"字段墙\"\"生态位\"这类\"多而有序\"的画面。\n */\nexport const Grid: React.FC<{\n  items: readonly string[]\n  columns?: number\n  cellW?: number\n  cellH?: number\n  gap?: number\n  start?: number\n  span?: number\n  delay?: number\n  size?: number\n  color?: string\n  /** 点亮项（下标或文本匹配），delay 后翻成强调色（每镜最多一次，勿群发）。 */\n  ignite?: number[]\n  igniteAt?: number\n  igniteColor?: string\n  align?: \"center\" | \"left\"\n}> = ({\n  items,\n  columns = 6,\n  cellW = 196,\n  cellH = 62,\n  gap = 14,\n  start = 0,\n  span = 90,\n  delay = 0,\n  size = 21,\n  color = C.textDim,\n  ignite = [],\n  igniteAt,\n  igniteColor = C.accent,\n  align = \"center\",\n}) => {\n  const frame = useCurrentFrame()\n  const rows = Math.ceil(items.length / columns)\n  const gridW = columns * cellW + (columns - 1) * gap\n  const gridH = rows * cellH + (rows - 1) * gap\n  const containerOpacity = p(frame, delay, T.small)\n  const isIgnited = (i: number): number => {\n    if (igniteAt === undefined) return 0\n    if (!ignite.includes(i)) return 0\n    return p(frame, igniteAt + ignite.indexOf(i) * 5, T.small)\n  }\n  return (\n    <div\n      style={{\n        width: gridW,\n        height: gridH,\n        display: \"grid\",\n        gridTemplateColumns: `repeat(${columns}, ${cellW}px)`,\n        gridAutoRows: `${cellH}px`,\n        gap,\n        opacity: containerOpacity,\n        justifyContent: align === \"center\" ? \"center\" : \"flex-start\",\n      }}\n    >\n      {items.map((label, i) => {\n        const on = accel(frame, i, items.length, start, span)\n        const hot = isIgnited(i)\n        return (\n          <div\n            key={label + i}\n            style={{\n              display: \"flex\",\n              alignItems: \"center\",\n              justifyContent: \"center\",\n              gap: 10,\n              border: `1px solid ${hot > 0 ? C.accentSoft : C.line}`,\n              borderRadius: 10,\n              background: hot > 0 ? `rgba(122,162,247,${0.06 + hot * 0.1})` : \"rgba(255,255,255,0.028)\",\n              opacity: on,\n              transform: `translateY(${(1 - on) * 14}px) scale(${0.94 + on * 0.06})`,\n            }}\n          >\n            <span\n              style={{\n                fontFamily: F.sans,\n                fontSize: size,\n                letterSpacing: \"0.02em\",\n                color: hot > 0 ? igniteColor : color,\n                opacity: 0.72 + on * 0.28,\n                whiteSpace: \"nowrap\",\n              }}\n            >\n              {label}\n            </span>\n          </div>\n        )\n      })}\n    </div>\n  )\n}\n\n/**\n * 节点流程 / 循环机制图：节点按给定角度排布，连线先画、节点后落位（可循环标注）。\n * 用于\"主循环\"\"因果链\"\"工作流\"这类机制说明——比堆文字更容易被看懂。\n */\nexport const NodeFlow: React.FC<{\n  nodes: readonly string[]\n  radius?: number\n  nodeSize?: number\n  delay?: number\n  lineDelay?: number\n  /** 首个节点的延迟。 */\n  nodeDelay?: number\n  /** 相邻节点的落位间隔（越密越局促，默认 42）。 */\n  nodeStep?: number\n  /** 圆形布局（true）或水平布局（false）。 */\n  circular?: boolean\n  centerLabel?: string\n  centerSize?: number\n  accent?: string\n  clockwise?: boolean\n}> = ({ nodes, radius = 240, nodeSize = 108, delay = 0, lineDelay = 0, nodeDelay = 40, nodeStep = 42, circular = true, centerLabel, centerSize = 30, accent = C.accent, clockwise = true }) => {\n  const frame = useCurrentFrame()\n  const n = nodes.length\n  const points = nodes.map((_, i) => {\n    const t = (i / n) * Math.PI * 2 - Math.PI / 2\n    return circular ? { x: 960 + Math.cos(t) * radius, y: 540 + Math.sin(t) * radius } : { x: 960 + (i - (n - 1) / 2) * radius, y: 540 }\n  })\n  const draw = p(frame, delay, lineDelay || T.big)\n  return (\n    <>\n      <svg width={1920} height={1080} style={{ position: \"absolute\", inset: 0, pointerEvents: \"none\" }}>\n        {points.map((pt, i) => {\n          const next = points[(i + 1) % n]\n          if (!circular && i === n - 1) return null\n          const segStart = i / n\n          const segEnd = (i + 1) / n\n          const local = clamp01(interpolate(draw, [segStart, segEnd], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" }))\n          const x2 = pt.x + (next.x - pt.x) * local\n          const y2 = pt.y + (next.y - pt.y) * local\n          return <line key={i} x1={pt.x} y1={pt.y} x2={x2} y2={y2} stroke=\"rgba(255,255,255,0.22)\" strokeWidth={1.5} strokeDasharray=\"0\" />\n        })}\n        {clockwise && circular\n          ? points.map((pt, i) => {\n              const next = points[(i + 1) % n]\n              const mid = { x: (pt.x + next.x) / 2, y: (pt.y + next.y) / 2 }\n              const on = p(frame, delay + T.big + i * 6, T.small)\n              const ang = (Math.atan2(next.y - pt.y, next.x - pt.x) * 180) / Math.PI\n              return (\n                <polygon\n                  key={`arrow-${i}`}\n                  points=\"0,-5 10,0 0,5\"\n                  fill={accent}\n                  opacity={on * 0.5}\n                  transform={`translate(${mid.x},${mid.y}) rotate(${ang})`}\n                />\n              )\n            })\n          : null}\n      </svg>\n      {points.map((pt, i) => {\n        const on = p(frame, nodeDelay + i * nodeStep, T.mid)\n        return (\n          <div\n            key={nodes[i]}\n            style={{\n              position: \"absolute\",\n              left: pt.x,\n              top: pt.y,\n              width: nodeSize,\n              height: nodeSize,\n              marginLeft: -nodeSize / 2,\n              marginTop: -nodeSize / 2,\n              borderRadius: \"50%\",\n              border: `1px solid ${C.lineStrong}`,\n              background: \"rgba(18,21,28,0.92)\",\n              backdropFilter: \"blur(10px)\",\n              display: \"flex\",\n              alignItems: \"center\",\n              justifyContent: \"center\",\n              opacity: on,\n              transform: `scale(${0.9 + on * 0.1})`,\n              boxShadow: `0 0 ${24 * on}px rgba(0,0,0,0.5)`,\n            }}\n          >\n            <span style={{ fontFamily: F.sans, fontSize: nodeSize * 0.19, color: C.text, letterSpacing: \"0.04em\", whiteSpace: \"nowrap\" }}>{nodes[i]}</span>\n          </div>\n        )\n      })}\n      {centerLabel ? (\n        <div style={{ position: \"absolute\", left: 960, top: 540, transform: \"translate(-50%, -50%)\", opacity: p(frame, nodeDelay, T.mid) }}>\n          <span style={{ fontFamily: F.serif, fontSize: centerSize, letterSpacing: \"0.14em\", color: C.text }}>{centerLabel}</span>\n        </div>\n      ) : null}\n    </>\n  )\n}\n\n/**\n * 数字滚动（指标）：整数位从 0 冲刺到目标值并带轻微过冲落定。\n * 千分位与小数位按 `decimals` 处理；货币/单位由 suffix/prefix 给出。\n */\nexport const DigitRoll: React.FC<{\n  value: number\n  delay?: number\n  duration?: number\n  size?: number\n  decimals?: number\n  prefix?: string\n  suffix?: string\n  color?: string\n  font?: string\n  overshoot?: number\n}> = ({ value, delay = 0, duration = T.big, size = 96, decimals = 0, prefix = \"\", suffix = \"\", color = C.text, font = F.mono, overshoot = 1.04 }) => {\n  const frame = useCurrentFrame()\n  const t = p(frame, delay, duration, EASE.out)\n  const boost = 1 + (1 - t) * (overshoot - 1) * Math.sin(Math.PI * clamp01(t))\n  const shown = value * t * boost\n  const text = shown.toLocaleString(\"en-US\", { minimumFractionDigits: decimals, maximumFractionDigits: decimals })\n  const on = p(frame, delay, T.small)\n  return (\n    <span style={{ fontFamily: font, fontSize: size, color, opacity: on, letterSpacing: \"0.02em\", whiteSpace: \"nowrap\" }}>\n      {prefix ? <span style={{ marginRight: \"0.08em\", opacity: 0.75 }}>{prefix}</span> : null}\n      {text}\n      {suffix ? <span style={{ marginLeft: \"0.08em\", opacity: 0.75 }}>{suffix}</span> : null}\n    </span>\n  )\n}\n\n/**\n * 闪切：跨镜头交棒的短促过场（闪白/闪黑/强调色）。\n * 惯例：`from` 给\"切点前几帧\"，由调用方在时间线上跨两个镜头摆放；用量要克制（全片 ≤3 处大冲击）。\n */\nexport const FlashCut: React.FC<{ duration?: number; color?: string; peak?: number; mode?: \"flash\" | \"dip\" }> = ({\n  duration = 10,\n  color = \"#ffffff\",\n  peak = 0.9,\n  mode = \"flash\",\n}) => {\n  const frame = useCurrentFrame()\n  const mid = duration / 2\n  const v = interpolate(frame, [0, mid, duration], mode === \"flash\" ? [0, 1, 0] : [1, 0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\" })\n  return <div style={{ position: \"absolute\", inset: 0, backgroundColor: color, opacity: v * peak, pointerEvents: \"none\" }} />\n}\n\n/**\n * 合影围标（结语）：一批元素从四面八方飞来，在字标周围就位——\"把已展示的东西一次性收拢\"。\n * 槽位为**显式排布**（外圈为主），中央留空给字标与标语，保证零遮挡。\n */\nexport const Roster: React.FC<{\n  items: readonly { text: string }[]\n  centerX?: number\n  centerY?: number\n  radiusX?: number\n  radiusY?: number\n  start?: number\n  span?: number\n  delay?: number\n  chipSize?: number\n  /** 环绕起始角（度）：槽位整体旋转，用于避开同屏其它元素（0 = 自正上方起，顺时针）。 */\n  rotation?: number\n  accent?: string\n}> = ({ items, centerX = 960, centerY = 540, radiusX = 640, radiusY = 330, start = 40, span = 240, delay = 0, chipSize = 19, rotation = 0, accent = C.accent }) => {\n  const frame = useCurrentFrame()\n  const containerOpacity = p(frame, delay, T.small)\n  return (\n    <div style={{ position: \"absolute\", inset: 0, opacity: containerOpacity }}>\n      {items.map((item, i) => {\n        const t = (i / items.length) * Math.PI * 2 - Math.PI / 2 + (rotation * Math.PI) / 180\n        const wobble = 0.88 + ((i * 37) % 11) / 11 * 0.18\n        const x = centerX + Math.cos(t) * radiusX * wobble\n        const y = centerY + Math.sin(t) * radiusY * wobble\n        const on = accel(frame, i, items.length, start, span)\n        const dx = x - centerX\n        const dy = y - centerY\n        const off = 2.1 * (1 - on)\n        return (\n          <div\n            key={item.text + i}\n            style={{\n              position: \"absolute\",\n              left: x,\n              top: y,\n              transform: `translate(-50%, -50%) translate(${dx * off}px, ${dy * off}px)`,\n            }}\n          >\n            <div\n              style={{\n                fontFamily: F.sans,\n                fontSize: chipSize,\n                letterSpacing: \"0.05em\",\n                color: C.text,\n                background: \"rgba(255,255,255,0.05)\",\n                border: `1px solid ${C.line}`,\n                borderRadius: 999,\n                padding: `${chipSize * 0.5}px ${chipSize * 1.05}px`,\n                whiteSpace: \"nowrap\",\n                opacity: on,\n                transform: `scale(${0.9 + on * 0.1})`,\n              }}\n            >\n              {item.text}\n            </div>\n          </div>\n        )\n      })}\n      <div\n        style={{\n          position: \"absolute\",\n          left: centerX,\n          top: centerY,\n          width: radiusX * 0.7,\n          height: radiusY * 0.68,\n          marginLeft: (-radiusX * 0.7) / 2,\n          marginTop: (-radiusY * 0.68) / 2,\n          borderRadius: \"50%\",\n          background: `radial-gradient(circle, ${accent}22 0%, transparent 70%)`,\n          opacity: p(frame, delay + 30, T.big),\n          pointerEvents: \"none\",\n        }}\n      />\n    </div>\n  )\n}\n",
  "src/index.ts": "import { registerRoot } from \"remotion\"\nimport { RemotionRoot } from \"./Root\"\n\nregisterRoot(RemotionRoot)\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"lib\": [\"DOM\", \"ES2022\"],\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"jsx\": \"react-jsx\",\n    \"strict\": true,\n    \"skipLibCheck\": true,\n    \"esModuleInterop\": true,\n    \"resolveJsonModule\": true,\n    \"noEmit\": true,\n    \"types\": [\"node\"]\n  },\n  \"include\": [\"src\"]\n}\n",
}

